INSERT INTO `t_question` VALUES (1,1,1,50,1,3,'A',1,3,1,'2026-03-07 16:22:43',_binary '\0',0),(2,5,1,10,1,4,'<p>白雪公主的妈妈</p>',7,2,1,'2026-03-12 00:26:17',_binary '\0',0),(3,1,1,50,1,3,'C',45,2,1,'2026-03-15 22:39:18',_binary '\0',0),(4,2,1,100,1,4,'A,B,D,F',47,2,1,'2026-03-15 22:43:47',_binary '\0',0),(5,3,1,20,1,2,'A',48,2,1,'2026-03-15 22:49:23',_binary '\0',0),(6,4,1,30,1,3,NULL,49,2,1,'2026-03-15 22:50:24',_binary '\0',0),(7,5,1,200,1,5,'<p>（1）结束了中国半殖民地半封建社会的历史；（2）实现了民族独立和人民解放；（3）为建设社会主义现代化国家奠定了基础；（4）开启了中华民族伟大复兴的历史征程；（5）改变了世界政治力量对比，壮大了世界和平民主力量。</p>',50,2,1,'2026-03-15 22:51:42',_binary '\0',0),(8,5,1,200,1,5,'<p>《原神》取得成功的主要原因包括： 1. 高品质的跨平台体验：游戏在PC、手机、主机等多平台同步上线，实现了数据互通，让玩家可以随时随地体验高质量的开放世界游戏。 2. 出色的美术设计与持续内容更新：游戏拥有精美的画面和独特的艺术风格，同时通过定期推出新角色、新地图和活动，保持了玩家的新鲜感和长期兴趣。 3. 全球化运营与本地化策略：游戏在全球多个国家和地区同步上线，并针对不同市场进行文化适配和营销推广，成功实现了中国游戏的全球化输出。</p>',51,2,1,'2026-03-15 23:47:03',_binary '\0',0),(17,1,1,50,1,3,'C',70,1,1,'2026-03-21 14:18:03',_binary '\0',0),(18,1,1,50,1,3,'D',71,1,1,'2026-03-21 14:18:03',_binary '\0',0),(19,1,1,50,1,3,'C',72,1,1,'2026-03-21 14:18:03',_binary '\0',0),(20,1,1,50,1,3,'B',73,1,1,'2026-03-21 14:18:03',_binary '\0',0),(21,1,1,50,1,3,'B',74,1,1,'2026-03-21 14:18:03',_binary '\0',0),(22,1,1,50,1,3,'B',75,1,1,'2026-03-21 14:18:03',_binary '\0',0),(23,1,1,50,1,3,'A',76,1,1,'2026-03-21 14:18:04',_binary '\0',0),(24,1,1,50,1,3,'B',77,1,1,'2026-03-21 14:18:04',_binary '\0',0),(25,1,1,50,1,3,'A',78,1,1,'2026-03-21 14:18:04',_binary '\0',0),(26,2,1,100,1,3,'A,B,C,D',79,1,1,'2026-03-21 14:18:04',_binary '\0',0),(27,3,1,20,1,3,'正确',80,1,1,'2026-03-21 14:18:04',_binary '\0',0),(28,4,1,50,1,3,'科举',81,1,1,'2026-03-21 14:18:04',_binary '\0',0),(29,5,1,200,1,3,'政治上：建立中央集权制度，确立皇帝至高无上的地位，在中央设三公九卿，在地方推行郡县制。经济上：统一货币（秦半两钱）、统一度量衡、统一车轨宽度。文化上：统一文字（小篆），焚书坑儒，狭小字。',82,1,1,'2026-03-21 14:18:04',_binary '\0',0),(30,1,1,50,1,3,'B',86,1,1,'2026-03-21 14:21:04',_binary '\0',0),(31,2,1,100,1,3,'A,B,D',87,1,1,'2026-03-21 14:21:04',_binary '\0',0),(32,3,1,20,1,3,'正确',88,1,1,'2026-03-21 14:21:04',_binary '\0',0),(33,4,1,50,1,3,'甲午中日战争,马关',89,1,1,'2026-03-21 14:21:04',_binary '\0',0),(34,5,1,200,1,3,'主要措施：\n1. 政治上：建立中央集权制度，废除分封制，推行郡县制\n2. 经济上：统一货币（秦半两）、统一度量衡\n3. 文化上：统一文字（小篆）\n4. 交通上：修建驰道、统一车轨宽度\n5. 军事上：修筑万里长城，抵御匈奴\n\n意义：这些措施巩固了秦朝的统一，加强了中央集权，促进了经济文化交流与发展，对后世产生了深远影响。',90,1,1,'2026-03-21 14:21:04',_binary '\0',0),(35,1,1,50,1,3,'B',94,1,1,'2026-03-21 14:26:47',_binary '\0',0),(36,2,1,100,1,3,'B,C,D',95,1,1,'2026-03-21 14:26:47',_binary '\0',0),(37,3,1,20,1,3,'错误',96,1,1,'2026-03-21 14:26:47',_binary '\0',0),(38,4,1,50,1,3,'消化道,消化腺,消化道',97,1,1,'2026-03-21 14:26:47',_binary '\0',0),(39,5,1,200,1,3,'1. 草→兔→狐\n2. 草减少会导致兔的数量减少（因为兔的食物不足），进而导致狐的数量减少（因为狐的食物来源——兔的数量减少）。',98,1,1,'2026-03-21 14:26:47',_binary '\0',0),(40,1,1,50,1,3,'C',102,1,1,'2026-03-21 14:56:29',_binary '\0',0),(41,2,1,100,1,3,'B,D',103,1,1,'2026-03-21 14:56:29',_binary '\0',0),(42,3,1,20,1,3,'错误',104,1,1,'2026-03-21 14:56:29',_binary '\0',0),(43,4,1,50,1,3,'儒,孔子,二十',105,1,1,'2026-03-21 14:56:29',_binary '\0',0),(44,5,1,200,1,3,'【参考答案】<br>主旨：这则故事通过俞伯牙和锺子期的故事，表达了知音难觅的道理。<br><br>道理：真正的知音能够理解对方的志趣和情感，真正的友谊是建立在相互理解和心灵相通的基础上的。',106,1,1,'2026-03-21 14:56:29',_binary '\0',0),(45,1,1,50,1,3,'A',110,1,1,'2026-03-21 15:05:10',_binary '\0',0),(46,2,1,100,1,3,'A,B',111,1,1,'2026-03-21 15:05:10',_binary '\0',0),(47,3,1,20,1,3,'错误',112,1,1,'2026-03-21 15:05:10',_binary '\0',0),(48,4,1,50,1,3,'南多北少,东南,西北',113,1,1,'2026-03-21 15:05:10',_binary '\0',0),(49,5,1,200,1,3,'秦岭-淮河一线是我国重要的地理分界线，其地理意义包括：<br>1. <b>南北方分界线</b>：秦岭-淮河一线以南属于南方地区，以北属于北方地区。<br>2. <b>暖温带与亚热带分界线</b>：此线以南为亚热带，以北为暖温带。<br>3. <b>湿润区与半湿润区分界线</b>：以南年降水量大于800mm，为湿润区；以北年降水量在400-800mm之间，为半湿润区。<br>4. <b>河流有无结冰期分界线</b>：以南河流冬季不结冰，以北河流冬季有结冰期。<br>5. <b>粮食作物分界线</b>：以南以水稻为主，以北以小麦为主。<br>6. <b>植被类型分界线</b>：以南为亚热带常绿阔叶林，以北为温带落叶阔叶林。',114,1,1,'2026-03-21 15:05:10',_binary '\0',0),(50,1,1,50,1,3,'A',116,1,1,'2026-03-21 15:06:47',_binary '\0',0),(51,2,1,100,1,3,'A,D',117,1,1,'2026-03-21 15:06:47',_binary '\0',0),(52,3,1,20,1,3,'正确',118,1,1,'2026-03-21 15:06:47',_binary '\0',0),(53,4,1,50,1,3,'东南沿海, 西北内陆, 水稻, 小麦',119,2,1,'2026-03-21 15:06:47',_binary '\0',0),(54,5,1,200,1,3,'（1）秦岭；淮河<br>（2）水田；旱地<br>（3）0',120,2,1,'2026-03-21 15:06:47',_binary '\0',0),(55,1,1,50,1,3,'C',126,2,1,'2026-03-21 17:36:29',_binary '\0',0),(56,2,1,100,1,3,'A,B,D',127,2,1,'2026-03-21 17:36:29',_binary '\0',0),(57,3,1,20,1,3,'正确',128,2,1,'2026-03-21 17:36:29',_binary '\0',0),(58,4,1,50,1,3,'细胞核,细胞核',129,2,1,'2026-03-21 17:36:29',_binary '\0',0),(59,5,1,200,1,3,'气体交换的原理是<b>扩散作用</b>。肺泡内的氧气浓度高于血液中的氧气浓度，因此氧气由肺泡扩散进入血液；同时，血液中的二氧化碳浓度高于肺泡内的二氧化碳浓度，因此二氧化碳由血液扩散进入肺泡。<br><br>影响气体交换效率的因素包括：<br>1. <b>呼吸膜的面积</b>：呼吸膜面积越大，气体交换效率越高；<br>2. <b>呼吸膜的厚度</b>：呼吸膜越薄，气体扩散的距离越短，交换效率越高；<br>3. <b>通气/血流比值</b>：通气量与血流量的比例适当，气体交换效率最高；<br>4. <b>气体的分压差</b>：分压差越大，扩散速率越快；<br>5. <b>气体的溶解度</b>：气体在血液中的溶解度影响扩散速率。',130,2,1,'2026-03-21 17:36:29',_binary '\0',0),(60,1,1,50,1,3,'D',132,2,1,'2026-03-21 17:39:16',_binary '\0',0),(61,2,1,100,1,3,'A,B,D',133,2,1,'2026-03-21 17:39:16',_binary '\0',0),(62,3,1,20,1,3,'错误',134,2,1,'2026-03-21 17:39:16',_binary '\0',0),(63,4,1,50,1,3,'水,氧气,化学能,有机物',135,2,1,'2026-03-21 17:39:16',_binary '\0',0),(64,5,1,200,1,3,'绿色植物光合作用的主要意义包括：<br><br>1. <b>合成有机物</b>：将光能转化为化学能，储存在有机物中，为植物自身生长提供营养物质。<br><br>2. <b>维持大气平衡</b>：吸收空气中的二氧化碳，释放氧气，保持大气中氧气和二氧化碳含量的相对稳定。<br><br>3. <b>为其他生物提供能量</b>：作为生态系统中的生产者，为动物和人类提供食物和氧气，是生物生存的基础。',136,2,1,'2026-03-21 17:39:16',_binary '\0',0),(65,1,1,50,1,3,'A',139,2,1,'2026-03-21 18:02:31',_binary '\0',1),(66,2,1,100,1,3,'A,B,C',140,2,1,'2026-03-21 18:02:31',_binary '\0',1),(67,3,1,20,1,3,'错误',141,2,1,'2026-03-21 18:02:31',_binary '\0',1),(68,4,1,50,1,3,'季风,东南沿海,西北内陆,南,北',142,2,1,'2026-03-21 18:02:31',_binary '\0',1),(69,5,1,200,1,3,'中国地形的主要特点：<br>1. <b>地形复杂多样</b>：包括山地、高原、平原、盆地、丘陵等多种地形类型。<br>2. <b>山区面积广大</b>：山区面积约占全国陆地面积的三分之二。<br>3. <b>地势西高东低</b>：呈三级阶梯状分布，第一级阶梯是青藏高原，第二级阶梯是高原和盆地，第三级阶梯是平原和丘陵。<br><br>对农业生产的影响：<br>1. <b>耕地资源有限</b>：平原面积仅占全国陆地面积的12%，耕地主要集中在东部季风区的平原和盆地。<br>2. <b>农业类型多样</b>：地形多样有利于发展多种农业类型，山区可发展林业和畜牧业，盆地可发展灌溉农业。<br>3. <b>气候条件差异大</b>：地势西高东低使东部地区受海洋季风影响，雨热同期，利于农业生产；而西部地区气候干旱，水源不足。',143,2,1,'2026-03-21 18:02:31',_binary '\0',1),(70,1,1,50,1,3,'C',145,1,1,'2026-03-21 18:27:35',_binary '\0',1),(71,2,1,100,1,3,'A,B,C',146,1,1,'2026-03-21 18:27:35',_binary '\0',1),(72,3,1,20,1,3,'错误',147,1,1,'2026-03-21 18:27:35',_binary '\0',1),(73,4,1,50,1,3,'公有制, 多种所有制经济',148,1,1,'2026-03-21 18:27:35',_binary '\0',1),(74,5,1,200,1,3,'（1）价值规律是商品经济的基本规律，其内容是：商品的价值量由生产该商品的社会必要劳动时间决定，商品交换以价值量为基础实行等价交换。<br>（2）社会必要劳动时间决定商品的价值量。企业提高劳动生产率，意味着生产商品的个别劳动时间低于社会必要劳动时间，在等价交换原则下，该企业的商品成本低于同类商品。<br>（3）当个别劳动时间低于社会必要劳动时间时，企业在相同时间内创造的商品价值总量更大，从而在市场竞争中处于有利地位，获得价格优势。<br>（4）因此，企业通过技术创新提高劳动生产率，是遵循价值规律、实现自身发展的有效途径。',149,1,1,'2026-03-21 18:27:35',_binary '\0',1),(75,1,1,50,1,3,'C',153,1,1,'2026-03-21 18:41:25',_binary '\0',1),(76,2,1,100,1,3,'A,B,C,D',154,1,1,'2026-03-21 18:41:25',_binary '\0',1),(77,3,1,20,1,3,'错误',155,1,1,'2026-03-21 18:41:25',_binary '\0',1),(78,4,1,50,1,3,'2, 1, 2',156,1,1,'2026-03-21 18:41:25',_binary '\0',1),(79,5,1,200,1,3,'<b>变质原因：</b>氢氧化钠溶液敞口放置时，会吸收空气中的二氧化碳气体，生成碳酸钠而变质。<br><br><b>反应方程式：</b>2NaOH + CO₂ = Na₂CO₃ + H₂O<br><br><b>检验方法：</b>取少量溶液于试管中，加入足量稀盐酸（或稀硫酸），若观察到有气泡产生，说明氢氧化钠已变质。<br><br>或：加入氯化钙（或氢氧化钙）溶液，若产生白色沉淀，说明已变质。',157,1,1,'2026-03-21 18:41:25',_binary '\0',1),(80,1,1,50,1,3,'B',179,1,1,'2026-04-01 00:17:35',_binary '\0',1),(81,1,1,50,1,3,'B',180,1,1,'2026-04-01 00:17:35',_binary '\0',1),(82,2,1,100,1,3,'A,B,C',181,1,1,'2026-04-01 00:17:35',_binary '\0',1),(83,3,1,20,1,3,'正确',182,1,1,'2026-04-01 00:17:35',_binary '\0',1),(84,4,1,50,1,3,'西高东低,东',183,1,1,'2026-04-01 00:17:35',_binary '\0',1),(85,5,1,200,1,3,'（1）A：青藏高原；B：塔里木盆地；C：东北平原；D：长江中下游平原<br>（2）秦岭；是南方和北方的重要分界线<br>（3）B地形区主要特征：气候干旱，降水稀少；以沙漠为主；地势相对平坦但四周高山环绕；蕴藏丰富的油气资源',184,1,1,'2026-04-01 00:17:35',_binary '\0',1),(86,1,1,50,1,3,'B',192,1,1,'2026-04-11 18:20:03',_binary '\0',1),(87,1,1,50,1,3,'B',193,1,1,'2026-04-11 18:20:03',_binary '\0',1),(88,2,1,100,1,3,'A,C,D',194,1,1,'2026-04-11 18:20:03',_binary '\0',1),(89,3,1,20,1,3,'正确',195,1,1,'2026-04-11 18:20:03',_binary '\0',1),(90,4,1,50,1,3,'西,东,三',196,1,1,'2026-04-11 18:20:03',_binary '\0',1),(91,5,1,200,1,3,'1. A：北方地区；B：南方地区；C：西北地区；D：青藏地区。<br>2. 主要差异：<br>   - <b>气候</b>：A（北方地区）以温带季风气候为主，冬季寒冷干燥，夏季高温多雨；B（南方地区）以亚热带季风气候为主，冬季温和少雨，夏季高温多雨，热量和降水更丰富。<br>   - <b>地形</b>：A以平原、高原为主（如东北平原、华北平原、黄土高原）；B以平原、丘陵、盆地为主（如长江中下游平原、东南丘陵、四川盆地）。<br>   - <b>植被</b>：A以温带落叶阔叶林为主；B以亚热带常绿阔叶林为主。<br>3. 有利自然条件：<br>   - 地形以高原、盆地和山地为主，草原、荒漠草原广布，草场资源丰富。<br>   - 属于温带大陆性气候，降水较少，晴天多，光照充足，有利于牧草生长和牲畜放牧。<br>   - 地广人稀，土地资源丰富，为畜牧业提供了广阔的空间。',197,1,1,'2026-04-11 18:20:03',_binary '\0',1),(92,1,2,50,2,3,'D',207,2,1,'2026-04-18 15:20:01',_binary '\0',1),(93,2,2,100,2,3,'A,B,C,D,E',208,2,1,'2026-04-18 15:20:01',_binary '\0',1),(94,3,2,20,2,3,'错误',209,2,1,'2026-04-18 15:20:01',_binary '\0',1),(95,4,2,50,2,3,'董仲舒,推恩令,五铢',210,2,1,'2026-04-18 15:20:01',_binary '\0',1),(96,5,2,200,2,3,'政治方面：<br>1. 创立皇帝制度，确立皇权至高无上。<br>2. 在中央实行三公九卿制，协助皇帝处理政务。<br>3. 在地方推行郡县制，由中央直接任命官员进行管理，取代了分封制。<br><br>经济方面：<br>1. 统一货币，规定圆形方孔半两钱为全国通行货币。<br>2. 统一度量衡，颁布标准器，便利了经济交流。<br>3. 统一车轨，修建以咸阳为中心的驰道，促进交通发展。<br><br>文化方面：<br>1. 统一文字，以小篆作为标准字体，后推广更简便的隶书。<br>2. 实行‘焚书坑儒’，加强思想控制，但也摧残了文化。<br><br>军事方面：<br>1. 北击匈奴，修筑万里长城，以防御北方游牧民族。<br>2. 南征百越，开凿灵渠，加强对岭南地区的控制。',211,2,1,'2026-04-18 15:20:01',_binary '\0',1),(97,1,4,50,1,3,'C',212,2,1,'2026-04-18 15:35:38',_binary '\0',1),(98,1,4,50,1,3,'C',213,2,1,'2026-04-18 15:35:38',_binary '\0',1),(99,2,4,100,1,3,'A,B,C',214,2,1,'2026-04-18 15:35:38',_binary '\0',1),(100,3,4,20,1,3,'错误',215,2,1,'2026-04-18 15:35:38',_binary '\0',1),(101,4,4,50,1,3,'李斯,休养生息',216,2,1,'2026-04-18 15:35:38',_binary '\0',1),(102,5,4,200,1,3,'主要原因：<br>1. <b>政治腐败与统治集团内部矛盾加剧</b>：唐玄宗后期沉湎享乐，任用奸相李林甫、杨国忠，导致朝政混乱，中央集权削弱。<br>2. <b>军事制度弊端显现</b>：均田制与府兵制瓦解，募兵制兴起，导致边镇节度使权力过大，形成‘外重内轻’的军事格局。<br>3. <b>社会矛盾激化</b>：土地兼并严重，均田农民破产流亡，租庸调制难以维持，政府财政困难。<br><br>安史之乱的影响：<br>1. <b>对唐朝的直接打击</b>：严重破坏了北方经济，人口锐减；中央权威一落千丈，形成藩镇割据局面；边疆防御空虚，吐蕃等势力乘机入侵。<br>2. <b>对历史进程的深远影响</b>：<br>   - <b>经济重心南移加速</b>：北方战乱促使人口、技术南迁，江南地区成为经济中心。<br>   - <b>政治格局变化</b>：开启了唐中后期乃至五代十国的藩镇割据传统，中央集权制面临长期挑战。<br>   - <b>民族关系与文化交流</b>：陆上丝绸之路受阻，对外交流重心部分转向海路；部分内迁少数民族加速汉化。',217,2,1,'2026-04-18 15:35:38',_binary '\0',1),(103,1,5,50,1,3,'C',223,2,1,'2026-04-18 15:50:33',_binary '\0',1),(104,1,5,50,1,3,'B',224,2,1,'2026-04-18 15:50:33',_binary '\0',1),(105,1,5,50,1,3,'C',225,2,1,'2026-04-18 15:50:33',_binary '\0',1),(106,1,5,50,1,3,'C',226,2,1,'2026-04-18 15:50:33',_binary '\0',1),(107,1,5,50,1,3,'D',227,2,1,'2026-04-18 15:50:33',_binary '\0',1),(108,1,5,50,1,2,'B',229,1,1,'2026-04-26 19:16:50',_binary '\0',1),(109,1,5,50,1,2,'A',230,1,1,'2026-04-26 19:16:50',_binary '\0',1),(110,1,5,50,1,2,'A',231,1,1,'2026-04-26 19:16:50',_binary '\0',1),(111,2,5,100,1,3,'A,D',232,1,1,'2026-04-26 19:16:50',_binary '\0',1),(112,2,5,100,1,2,'A,C',233,1,1,'2026-04-26 19:16:50',_binary '\0',1),(113,1,5,50,1,2,'C',235,2,1,'2026-04-26 19:21:55',_binary '\0',1),(114,1,5,50,1,2,'C',236,2,1,'2026-04-26 19:21:55',_binary '\0',1),(115,1,5,50,1,2,'C',237,2,1,'2026-04-26 19:21:55',_binary '\0',1),(116,2,5,100,1,2,'A,B,C',238,2,1,'2026-04-26 19:21:55',_binary '\0',1),(117,1,5,50,1,2,'C',239,1,1,'2026-04-26 19:22:15',_binary '\0',1),(118,1,5,50,1,2,'C',240,1,1,'2026-04-26 19:22:15',_binary '\0',1),(119,1,5,50,1,2,'B',241,1,1,'2026-04-26 19:22:15',_binary '\0',1),(120,2,5,100,1,2,'A,B,C,D',242,1,1,'2026-04-26 19:22:15',_binary '\0',1);
