INSERT INTO `t_question_revision_log` VALUES (1,8,1,'student_solution_adopted','','原神是什么东西',2,1,'2026-04-16 23:33:42'),(2,8,1,'feedback_update','{\"id\":8,\"questionType\":5,\"subjectId\":1,\"title\":\"<p>请简述《原神》在全球市场取得成功的三个主要原因</p>\",\"userGroupId\":1,\"items\":[],\"analyze\":\"<p>本题要求学生分析《原神》成功的原因，属于游戏产业分析类题目。答题时需要从多个维度展开，包括产品品质、运营策略、市场定位等。回答时应条理清晰，选取最具代表性的三个因素进行阐述。</p>\",\"correctArray\":null,\"correct\":\"<p>《原神》取得成功的主要原因包括： 1. 高品质的跨平台体验：游戏在PC、手机、主机等多平台同步上线，实现了数据互通，让玩家可以随时随地体验高质量的开放世界游戏。 2. 出色的美术设计与持续内容更新：游戏拥有精美的画面和独特的艺术风格，同时通过定期推出新角色、新地图和活动，保持了玩家的新鲜感和长期兴趣。 3. 全球化运营与本地化策略：游戏在全球多个国家和地区同步上线，并针对不同市场进行文化适配和营销推广，成功实现了中国游戏的全球化输出。</p>\",\"score\":\"20\",\"difficult\":5,\"itemOrder\":null,\"isAi\":0,\"tagIds\":[],\"newTagNames\":null,\"tagNames\":[],\"gradeLevel\":1}','{\"id\":8,\"questionType\":5,\"subjectId\":1,\"title\":\"<p>请简述《原神》在全球市场取得成功的三个主要原因</p>\",\"userGroupId\":1,\"items\":[],\"analyze\":\"<p>本题要求学生分析《原神》成功的原因，属于游戏产业分析类题目。答题时需要从多个维度展开，包括产品品质、运营策略、市场定位等。回答时应条理清晰，选取最具代表性的三个因素进行阐述。</p>\",\"correctArray\":null,\"correct\":\"<p>《原神》取得成功的主要原因包括： 1. 高品质的跨平台体验：游戏在PC、手机、主机等多平台同步上线，实现了数据互通，让玩家可以随时随地体验高质量的开放世界游戏。 2. 出色的美术设计与持续内容更新：游戏拥有精美的画面和独特的艺术风格，同时通过定期推出新角色、新地图和活动，保持了玩家的新鲜感和长期兴趣。 3. 全球化运营与本地化策略：游戏在全球多个国家和地区同步上线，并针对不同市场进行文化适配和营销推广，成功实现了中国游戏的全球化输出。</p>\",\"score\":\"20\",\"difficult\":5,\"itemOrder\":null,\"isAi\":0,\"tagIds\":[],\"newTagNames\":[\"垃圾题\"],\"tagNames\":[],\"gradeLevel\":1}',2,1,'2026-04-16 23:38:46'),(3,105,1,'student_solution_adopted','','一眼看过去ACD全错，所以选B',2,2,'2026-04-18 16:09:16');
